@Test
public void testFlush() throws Exception {
    PhysicalWriter.OutputReceiver receiver = Mockito.mock(PhysicalWriter.OutputReceiver.class);
    CompressionCodec codec = new ZlibCodec();
    StreamOptions options = new StreamOptions(128 * 1024).withCodec(codec, codec.createOptions());
    OutStream stream = new OutStream("test", options, receiver);
    assertEquals(0L, stream.getBufferSize());
    stream.write(new byte[] { 0, 1, 2 });
    stream.flush();
    Mockito.verify(receiver).output(Mockito.any(ByteBuffer.class));
    assertEquals(0L, stream.getBufferSize());
}

